'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// FIXTURES //

var largeD1 = require( './fixtures/julia/large_d1.json' );
var largeD2 = require( './fixtures/julia/large_d2.json' );
var bothLarge = require( './fixtures/julia/both_large.json' );
var cppLargeD1 = require( './fixtures/cpp/large_d1.json' );
var cppLargeD2 = require( './fixtures/cpp/large_d2.json' );
var cppBothLarge = require( './fixtures/cpp/both_large.json' );


// VARIABLES //

var pdf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( pdf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof pdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', opts, function test( t ) {
	var y = pdf( NaN, 0.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = pdf( 0.0, NaN, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = pdf( 0.0, 1.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `+infinity` for `x` and a finite `d1` and `d2`, the function returns `0`', opts, function test( t ) {
	var y = pdf( PINF, 1.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );
	t.end();
});

tape( 'if provided `-infinity` for `x` and a finite `d1` and `d2`, the function returns `0`', opts, function test( t ) {
	var y = pdf( NINF, 1.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );
	t.end();
});

tape( 'if provided `d1 <= 0`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = pdf( 2.0, -1.0, 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.0, -1.0, 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 2.0, NINF, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 2.0, NINF, PINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 2.0, NINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 2.0, NINF, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `d2 <= 0`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = pdf( 2.0, 2.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.0, 2.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 2.0, 1.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 2.0, PINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 2.0, NINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 2.0, NaN, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `d1 < 2.0`, the function returns `+Infinity` when provided `0.0` for `x`', opts, function test( t ) {
	var y;

	y = pdf( 0.0, 1.0, 1.0 );
	t.strictEqual( y, PINF, 'returns expected value' );

	y = pdf( 0.0, 1.5, 1.0 );
	t.strictEqual( y, PINF, 'returns expected value' );

	t.end();
});

tape( 'if provided `d1 = 2.0`, the function returns `1.0` when provided `0.0` for `x`', opts, function test( t ) {
	var y;

	y = pdf( 0.0, 2.0, 1.0 );
	t.strictEqual( y, 1.0, 'returns expected value' );

	y = pdf( 0.0, 2.0, 3.0 );
	t.strictEqual( y, 1.0, 'returns expected value' );

	t.end();
});

tape( 'if provided `d1 > 2.0`, the function returns `0.0` when provided `0.0` for `x`', opts, function test( t ) {
	var y;

	y = pdf( 0.0, 3.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = pdf( 0.0, 3.5, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the pdf for a baseline case', opts, function test( t ) {
	var y = pdf( 2.0, 1.0, 1.0 );
	t.strictEqual( isAlmostSameValue( y, 0.07502635967975883, 2 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function evaluates the pdf for `x` given large `d1` and `d2` (tested against Julia)', opts, function test( t ) {
	var expected;
	var d1;
	var d2;
	var x;
	var y;
	var i;

	expected = bothLarge.expected;
	x = bothLarge.x;
	d1 = bothLarge.d1;
	d2 = bothLarge.d2;
	for ( i = 0; i < x.length; i++ ) {
		y = pdf( x[i], d1[i], d2[i] );
		if ( y === expected[i] ) {
			t.strictEqual( y, expected[i], 'x: '+x[i]+', d1: '+d1[i]+', d2: '+d2[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.ok( isAlmostSameValue( y, expected[i], 5000 ), 'within tolerance. x: '+x[ i ]+'. d1: '+d1[i]+'. d2: '+d2[i]+'. y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});

